Source code in <code>briefml/api/predictor.py</code> <pre><code>@app.post("/predict", response_model=PredictResponse)
def predict(req: PredictRequest) -&gt; PredictResponse:
    if MODEL is None or META is None:
        raise HTTPException(
            status_code=503, detail="Modèle non prêt (startup en cours)."
        )

    X = normalize_input(dict(req.data), META)

    proba = float(MODEL.predict_proba(X)[0, 1])
    threshold = float(META.threshold)
    pred_class = int(proba &gt;= threshold)
    label = "grave" if pred_class == 1 else "non_grave"

    return PredictResponse(
        proba=proba, pred_class=pred_class, label=label, threshold=threshold
    )
